import React, { useMemo, useEffect } from "react";
import {
  useCurrentFrame,
  useVideoConfig,
  AbsoluteFill,
  interpolate,
  spring,
} from '../remotionShim';
{/* Start Google Fonts Loader */}
const useFontLoader = (fonts: string[]) => {
  const stableFonts = useMemo(() => {
    const unique = [...new Set(fonts.map((f) => f.trim()))].sort();
    return unique;
  }, [fonts.join("|")]);

  useEffect(() => {
    if (typeof document === "undefined") return;

    const unloaded = stableFonts.filter(
      (font) =>
        !document.querySelector(`link[href*="${font.replace(/\s+/g, "+")}"]`)
    );

    if (unloaded.length === 0) return;

    const url = `https://fonts.googleapis.com/css2?${unloaded
      .map((font) => `family=${font.replace(/\s+/g, "+")}:wght@400;500;600`)
      .join("&")}&display=swap`;

    const link = document.createElement("link");
    link.rel = "stylesheet";
    link.href = url;

    document.head.appendChild(link);
  }, [stableFonts]);
};
{/* End Google Fonts Loader */}

// === THEMES & UTILS ===
const THEMES = {
  iMessage: {
    receiverColor: "#e5e5ea",
    receiverTextColor: "#000000",
    senderColor: "#007aff",
    senderTextColor: "#ffffff",
    borderRadius: 35,
  },
  WhatsApp: {
    receiverColor: "#ffffff",
    receiverTextColor: "#000000",
    senderColor: "#dcf8c6",
    senderTextColor: "#000000",
    borderRadius: 16,
  },
  Messenger: {
    receiverColor: "#f1f0f0",
    receiverTextColor: "#000000",
    senderColor: "#0084ff",
    senderTextColor: "#ffffff",
    borderRadius: 35,
  },
  Custom: {
    receiverColor: "#f1f0f0",
    receiverTextColor: "#000000",
    senderColor: "#000000",
    senderTextColor: "#ffffff",
    borderRadius: 35,
  },
};

const TypingDots: React.FC<{ color: string; frame: number; size: number }> = ({ 
  color, 
  frame, 
  size 
}) => {
  return (
    <div style={{ 
      display: "flex", 
      gap: size * 0.6, 
      alignItems: "center", 
      height: size * 1.5,
      transition: "none"
    }}>
      {[0, 1, 2].map((i) => {
        const opacity = interpolate(
          Math.sin(frame / 5 + i * 1.5),
          [-1, 1],
          [0.3, 1],
          {
            extrapolateLeft: "clamp",
            extrapolateRight: "clamp",
          }
        );
        return (
          <div
            key={i}
            style={{
              width: size,
              height: size,
              borderRadius: "50%",
              backgroundColor: color,
              opacity,
              transition: "none",
            }}
          />
        );
      })}
    </div>
  );
};

// === SCHEMA ===


export type ChatSequenceProps = Record<string, any>;

// === COMPONENT ===
const ChatSequence: React.FC<ChatSequenceProps> = ({
  backgroundColor = "#ffffff",
  transparentBackground = false,
  theme = "iMessage",
  customSenderColor = "#0084ff",
  customReceiverColor = "#f1f0f0",
  durationInSeconds = 15,
  messages = [
    { text: "I need to make a promotional video but I'm short on time.", isSender: false },
    { text: "Have you tried Malloy Studio? It turns text into motion graphics.", isSender: true },
    { text: "Wait, so it generates actual animations?", isSender: false },
    { text: "Exactly. It creates smooth, professional motion instantly.", isSender: true },
    { text: "Can I customize the branding and colors?", isSender: false },
    { text: "Yes, you have complete control to tweak every detail.", isSender: true },
    { text: "That sounds like a game changer.", isSender: false },
    { text: "It is. Just type your idea and watch it render.", isSender: true },
  ],
}) => {
  
  useFontLoader(["Inter"]);
  
  const frame = useCurrentFrame();
  const { fps, width, height } = useVideoConfig();

  const activeMessages = useMemo(() => {
    return messages.filter((m) => m && m.text && m.text.length > 0);
  }, [messages]);

  const totalDurationFrames = durationInSeconds * fps;
  const msgCount = Math.max(1, activeMessages.length);
  const cycleDurationFrames = totalDurationFrames / msgCount;

  // 60% typing indicator, 40% message read time per block
  const typingDurationFrames = cycleDurationFrames * 0.6;
  const messageGapFrames = cycleDurationFrames * 0.4;

  const activeTheme = useMemo(() => {
    const base = THEMES[theme] || THEMES["iMessage"];
    if (theme === "Custom") {
      return {
        ...base,
        senderColor: customSenderColor,
        receiverColor: customReceiverColor,
      };
    }
    return base;
  }, [theme, customSenderColor, customReceiverColor]);

  const bgColor = transparentBackground ? "transparent" : backgroundColor;
  
  // Canvas-aware scaling reference
  const s = Math.min(width, height);
  const scaleMultiplier = s / 1080;

  return (
    <AbsoluteFill
      style={{
        backgroundColor: bgColor,
        fontFamily: "'Inter', sans-serif",
        transition: "none",
      }}
    >
      <div
        style={{
          display: "flex",
          flexDirection: "column",
          width: "100%",
          height: "100%",
          paddingTop: height * 0.15,
          paddingBottom: height * 0.1,
          paddingLeft: width * 0.05,
          paddingRight: width * 0.05,
          justifyContent: "flex-end",
          alignItems: "center",
          boxSizing: "border-box",
          transition: "none",
        }}
      >
        <div
          style={{
            display: "flex",
            flexDirection: "column",
            width: "100%",
            maxWidth: width * 0.9,
            gap: 24 * scaleMultiplier,
            transition: "none",
          }}
        >
          {activeMessages.map((msg, index) => {
            const startTime = index * (typingDurationFrames + messageGapFrames);
            const typingEndTime = startTime + typingDurationFrames;
            
            // Phase 1: Typing Indicator
            const showTyping = frame >= startTime && frame < typingEndTime;
            const typingEnter = spring({
              frame: frame - startTime,
              fps,
              config: { damping: 20, stiffness: 200 },
            });

            // Phase 2: Message Reveal
            const showMessage = frame >= typingEndTime;
            const msgEnter = spring({
              frame: frame - typingEndTime,
              fps,
              config: { damping: 15, stiffness: 120 },
            });

            const isSender = msg.isSender;
            const bubbleColor = isSender ? activeTheme.senderColor : activeTheme.receiverColor;
            const textColor = isSender ? activeTheme.senderTextColor : activeTheme.receiverTextColor;
            const alignSelf = isSender ? "flex-end" : "flex-start";
            const borderRadiusPx = activeTheme.borderRadius * scaleMultiplier;

            const typingScale = Math.max(0, typingEnter); 
            const msgScale = Math.max(0, msgEnter);

            // Opacity handles fade in smoothly without CSS transitions
            const msgOpacity = interpolate(msgEnter, [0, 1], [0, 1], {
              extrapolateLeft: "clamp",
              extrapolateRight: "clamp",
            });

            return (
              <div
                key={index}
                style={{
                  display: "flex",
                  flexDirection: "column",
                  alignSelf,
                  maxWidth: "85%",
                  transition: "none",
                }}
              >
                {/* TYPING BUBBLE */}
                {showTyping && (
                  <div
                    style={{
                      backgroundColor: bubbleColor,
                      padding: `${20 * scaleMultiplier}px ${28 * scaleMultiplier}px`,
                      borderRadius: borderRadiusPx,
                      alignSelf,
                      alignItems: "center",
                      justifyContent: "center",
                      width: "fit-content",
                      transform: `scale(${typingScale})`,
                      transformOrigin: isSender ? "bottom right" : "bottom left",
                      transition: "none",
                    }}
                  >
                     <TypingDots 
                        color={textColor === "#ffffff" ? "rgba(255,255,255,0.7)" : "rgba(0,0,0,0.5)"} 
                        frame={frame} 
                        size={12 * scaleMultiplier} 
                      />
                  </div>
                )}

                {/* ACTUAL MESSAGE BUBBLE */}
                {showMessage && (
                  <div
                    style={{
                      backgroundColor: bubbleColor,
                      color: textColor,
                      padding: `${20 * scaleMultiplier}px ${28 * scaleMultiplier}px`,
                      borderRadius: borderRadiusPx,
                      borderBottomRightRadius: isSender ? 8 * scaleMultiplier : borderRadiusPx,
                      borderBottomLeftRadius: !isSender ? 8 * scaleMultiplier : borderRadiusPx,
                      fontSize: 34 * scaleMultiplier,
                      fontWeight: 500,
                      lineHeight: 1.4,
                      boxShadow: "0 4px 12px rgba(0,0,0,0.06)",
                      transform: `scale(${msgScale})`,
                      opacity: msgOpacity,
                      transformOrigin: isSender ? "bottom right" : "bottom left",
                      transition: "none",
                    }}
                  >
                    {msg.text}
                  </div>
                )}
              </div>
            );
          })}
        </div>
      </div>
    </AbsoluteFill>
  );
};

export default ChatSequence;